package application.domain.services.cart;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport; import java.util.*;
public class AddProductToCartService implements AddProductToCartUseCase { private final CartRepositoryPort carts; private final CustomerRepositoryPort customers; private final ProductRepositoryPort products; private final InventoryRepositoryPort inventories; private final OperationAuditPort audit;
 public AddProductToCartService(CartRepositoryPort c,CustomerRepositoryPort cu,ProductRepositoryPort p,InventoryRepositoryPort i,OperationAuditPort a){carts=c;customers=cu;products=p;inventories=i;audit=a;}
 public Cart addProduct(User actor,String cid,String pid,int quantity){Customer c=ServiceSupport.required(customers.findById(cid),"Customer",cid);ServiceSupport.sameCustomer(actor,c);Product p=ServiceSupport.required(products.findById(pid),"Product",pid);if(p.getStatus()!=application.domain.enums.ProductStatus.PUBLISHED)throw new IllegalArgumentException("Product is not active");Inventory inv=ServiceSupport.required(inventories.findByProduct(p),"Inventory",pid);if(inv.getAvailable()<quantity)throw new IllegalArgumentException("Insufficient stock");Cart cart=ServiceSupport.required(carts.findActiveByCustomer(c),"Cart",cid);cart.add(p,quantity);carts.update(cart);audit.record(actor,"ADD_PRODUCT_TO_CART",cart.getId(),Map.of("productId",pid,"quantity",quantity));return cart;}
}
